use std::ffi::{CStr, CString};
use std::os::raw::c_char;
use std::sync::{Arc, OnceLock};
use gf_gameforge::Zaibatsu;

static RUNTIME: OnceLock<tokio::runtime::Runtime> = OnceLock::new();
fn rt() -> &'static tokio::runtime::Runtime { RUNTIME.get_or_init(|| tokio::runtime::Builder::new_multi_thread().worker_threads(2).enable_all().build().expect("ffi runtime")) }

pub struct GfZaibatsu { inner: Arc<Zaibatsu> }
#[no_mangle] pub extern "C" fn gf_zaibatsu_create() -> *mut GfZaibatsu { Box::into_raw(Box::new(GfZaibatsu { inner: Arc::new(Zaibatsu::new()) })) }
#[no_mangle] pub unsafe extern "C" fn gf_zaibatsu_destroy(h: *mut GfZaibatsu) { if !h.is_null() { drop(Box::from_raw(h)); } }
unsafe fn handle<'a>(h:*const GfZaibatsu)->Option<&'a GfZaibatsu>{if h.is_null(){None}else{Some(&*h)}}
fn to_c(s:String)->*mut c_char{match CString::new(s){Ok(c)=>c.into_raw(),Err(_)=>std::ptr::null_mut()}}
fn err_json(msg:&str)->*mut c_char{to_c(serde_json::json!({"error":msg}).to_string())}
unsafe fn from_c<'a>(p:*const c_char)->&'a str{if p.is_null(){return ""}CStr::from_ptr(p).to_str().unwrap_or("")}
#[no_mangle] pub unsafe extern "C" fn gf_free_string(p:*mut c_char){if !p.is_null(){drop(CString::from_raw(p));}}

#[no_mangle] pub unsafe extern "C" fn gf_propose(h:*const GfZaibatsu,ledger:*const c_char,kind:*const c_char,proposal_id:*const c_char,attester:*const c_char,value_json:*const c_char)->*mut c_char{
 let Some(z)=handle(h)else{return err_json("null handle")};let value:serde_json::Value=serde_json::from_str(from_c(value_json)).unwrap_or(serde_json::Value::Null);let ledger=from_c(ledger).to_string();let kind=from_c(kind).to_string();let proposal_id=from_c(proposal_id).to_string();let attester=from_c(attester).to_string();let z=z.inner.clone();let(verdict,ev)=rt().block_on(async move{z.propose(&ledger,&kind,&proposal_id,&attester,value).await});to_c(serde_json::json!({"verdict":format!("{:?}",verdict).to_lowercase(),"event_id":ev.as_ref().map(|e|e.id.clone()),"seq":ev.as_ref().map(|e|e.seq)}).to_string())}
#[no_mangle] pub unsafe extern "C" fn gf_fabric_tail(h:*const GfZaibatsu,ledger:*const c_char,limit:u32)->*mut c_char{let Some(z)=handle(h)else{return err_json("null handle")};let ledger=from_c(ledger).to_string();let z=z.inner.clone();let events=rt().block_on(async move{z.fabric.tail(&ledger,limit as usize).await});to_c(serde_json::to_string(&events).unwrap_or_else(|_|"[]".into()))}
#[no_mangle] pub unsafe extern "C" fn gf_fabric_seq(h:*const GfZaibatsu)->u64{match handle(h){Some(z)=>{let z=z.inner.clone();rt().block_on(async move{z.fabric.current_seq().await})},None=>0}}
#[no_mangle] pub unsafe extern "C" fn gf_legion_found(h:*const GfZaibatsu,name:*const c_char,motto:*const c_char)->*mut c_char{let Some(z)=handle(h)else{return err_json("null handle")};let name=from_c(name).to_string();let motto=from_c(motto).to_string();let z=z.inner.clone();let l=rt().block_on(async move{z.legions.found(&name,&motto).await});to_c(serde_json::to_string(&l).unwrap())}
#[no_mangle] pub unsafe extern "C" fn gf_legion_enlist(h:*const GfZaibatsu,legion:*const c_char,capability:*const c_char)->*mut c_char{let Some(z)=handle(h)else{return err_json("null handle")};let legion=from_c(legion).to_string();let capability=from_c(capability).to_string();let z=z.inner.clone();match rt().block_on(async move{z.legions.enlist(&legion,&capability).await}){Some(member_id)=>to_c(serde_json::json!({"member_id":member_id}).to_string()),None=>err_json("no such legion")}}
#[no_mangle] pub unsafe extern "C" fn gf_swarm_submit(h:*const GfZaibatsu,task_id:*const c_char,capability:*const c_char,payload_json:*const c_char,deps_json:*const c_char)->*mut c_char{let Some(z)=handle(h)else{return err_json("null handle")};let id=from_c(task_id).to_string();let capability=from_c(capability).to_string();let payload=serde_json::from_str(from_c(payload_json)).unwrap_or(serde_json::Value::Null);let deps:Vec<String>=serde_json::from_str(from_c(deps_json)).unwrap_or_default();let z=z.inner.clone();match rt().block_on(async move{z.swarm.submit(&id,&capability,payload,deps).await}){Ok(())=>to_c(serde_json::json!({"submitted":id}).to_string()),Err(e)=>err_json(&format!("{e:?}"))}}
#[no_mangle] pub unsafe extern "C" fn gf_swarm_wave(h:*const GfZaibatsu)->*mut c_char{let Some(z)=handle(h)else{return err_json("null handle")};let z=z.inner.clone();let wave=rt().block_on(async move{z.swarm.ready_wave().await});to_c(serde_json::to_string(&wave).unwrap_or_else(|_|"[]".into()))}
#[no_mangle] pub unsafe extern "C" fn gf_governance_decide(h:*const GfZaibatsu,domain:*const c_char,action:*const c_char,actor_weight:u32)->*mut c_char{let Some(z)=handle(h)else{return err_json("null handle")};let domain=from_c(domain).to_string();let action=from_c(action).to_string();let z=z.inner.clone();let d=rt().block_on(async move{z.governance.decide(&domain,&action,actor_weight).await});to_c(serde_json::to_string(&d).unwrap())}
#[no_mangle] pub unsafe extern "C" fn gf_cognition_hold(h:*const GfZaibatsu,predicate:*const c_char,polarity:bool)->*mut c_char{let Some(z)=handle(h)else{return err_json("null handle")};let predicate=from_c(predicate).to_string();let z=z.inner.clone();let id=rt().block_on(async move{z.cognition.hold(&predicate,polarity).await});to_c(serde_json::json!({"belief_id":id}).to_string())}
#[no_mangle] pub unsafe extern "C" fn gf_cognition_testify(h:*const GfZaibatsu,belief_id:*const c_char,witness:*const c_char,supports:bool,weight:f64)->*mut c_char{let Some(z)=handle(h)else{return err_json("null handle")};let belief_id=from_c(belief_id).to_string();let witness=from_c(witness).to_string();let z=z.inner.clone();match rt().block_on(async move{z.cognition.testify(&belief_id,&witness,supports,weight).await}){Some(confidence)=>to_c(serde_json::json!({"confidence":confidence}).to_string()),None=>err_json("no such belief")}}
#[no_mangle] pub unsafe extern "C" fn gf_lafs_put(h:*const GfZaibatsu,data:*const u8,len:usize)->*mut c_char{let Some(z)=handle(h)else{return err_json("null handle")};let bytes:&[u8]=if len==0{&[]}else{if data.is_null(){return err_json("null data")}std::slice::from_raw_parts(data,len)};let z=z.inner.clone();match rt().block_on(async move{z.lafs.put_chunk(bytes).await}){Ok(digest)=>to_c(serde_json::json!({"digest":digest}).to_string()),Err(e)=>err_json(e)}}
#[no_mangle] pub unsafe extern "C" fn gf_status(h:*const GfZaibatsu)->*mut c_char{let Some(z)=handle(h)else{return err_json("null handle")};let z=z.inner.clone();let out=rt().block_on(async move{serde_json::json!({"fabric_seq":z.fabric.current_seq().await,"delta":z.delta.stats().await,"cognition":z.cognition.stats().await,"lafs":z.lafs.stats().await,"swarm":z.swarm.stats().await,"suspects":z.court.suspects().await})});to_c(out.to_string())}
